namespace Fps.Desktop.Rendering;

internal static class OutlineShaders
{
	private const string Sampling = "#version 330\nin vec2 fragTexCoord;\nout vec4 finalColor;\nuniform vec2 texel;\nuniform vec2 clipPlanes;\nuniform vec2 viewScale;\n\nfloat linearDepth(float depth) {\n    return clipPlanes.x * clipPlanes.y / mix(clipPlanes.y, clipPlanes.x, depth);\n}\n\nvec3 viewPosition(vec2 uv, float depth) {\n    return vec3((uv * 2.0 - 1.0) * viewScale, -1.0) * depth;\n}\n";

	public const string ReconstructNormals = "#version 330\nin vec2 fragTexCoord;\nout vec4 finalColor;\nuniform vec2 texel;\nuniform vec2 clipPlanes;\nuniform vec2 viewScale;\n\nfloat linearDepth(float depth) {\n    return clipPlanes.x * clipPlanes.y / mix(clipPlanes.y, clipPlanes.x, depth);\n}\n\nvec3 viewPosition(vec2 uv, float depth) {\n    return vec3((uv * 2.0 - 1.0) * viewScale, -1.0) * depth;\n}\nuniform sampler2D texture0;\n\nvec3 axisSlope(vec2 uv, vec2 stepUv, float raw, vec3 center) {\n    float left = texture(texture0, uv - stepUv).r;\n    float left2 = texture(texture0, uv - 2.0 * stepUv).r;\n    float right = texture(texture0, uv + stepUv).r;\n    float right2 = texture(texture0, uv + 2.0 * stepUv).r;\n    // Em uma face plana, a profundidade projetada varia linearmente.\n    // A extrapolação escolhe o lado menos afetado por uma silhueta.\n    if (abs(2.0 * left - left2 - raw) < abs(2.0 * right - right2 - raw))\n        return center - viewPosition(uv - stepUv, linearDepth(left));\n\n    return viewPosition(uv + stepUv, linearDepth(right)) - center;\n}\n\nvoid main() {\n    vec2 uv = fragTexCoord;\n    float raw = texture(texture0, uv).r;\n    if (raw >= 1.0) {\n        finalColor = vec4(0.0);\n        return;\n    }\n    vec3 point = viewPosition(uv, linearDepth(raw));\n    vec3 dx = axisSlope(uv, vec2(texel.x, 0.0), raw, point);\n    vec3 dy = axisSlope(uv, vec2(0.0, texel.y), raw, point);\n    vec3 crossSlope = cross(dx, dy);\n    float lengthSquared = dot(crossSlope, crossSlope);\n    vec3 normal = lengthSquared > 1e-16 ? crossSlope * inversesqrt(lengthSquared) : vec3(0.0, 0.0, 1.0);\n    finalColor = vec4(normal * 0.5 + 0.5, 1.0);\n}";

	public const string Composite = "#version 330\nin vec2 fragTexCoord;\nout vec4 finalColor;\nuniform vec2 texel;\nuniform vec2 clipPlanes;\nuniform vec2 viewScale;\n\nfloat linearDepth(float depth) {\n    return clipPlanes.x * clipPlanes.y / mix(clipPlanes.y, clipPlanes.x, depth);\n}\n\nvec3 viewPosition(vec2 uv, float depth) {\n    return vec3((uv * 2.0 - 1.0) * viewScale, -1.0) * depth;\n}\nuniform sampler2D texture0;\nuniform sampler2D depthMap;\nuniform sampler2D normalMap;\nuniform vec4 outlineColor;\nuniform vec4 thicknessAndDistance;\nuniform vec4 edgeThresholds;\n\nconst vec2 axes[4] = vec2[4](vec2(1, 0), vec2(0, 1), vec2(1, 1), vec2(1, -1));\n\nfloat depthAt(vec2 uv) {\n    return linearDepth(texture(depthMap, uv).r);\n}\n\nvec3 normalAt(vec2 uv, vec3 fallback) {\n    vec4 sampleNormal = texture(normalMap, uv);\n    return sampleNormal.a >= 0.5 ? sampleNormal.rgb / sampleNormal.a * 2.0 - 1.0 : fallback;\n}\n\nvoid main() {\n    vec2 uv = fragTexCoord;\n    vec4 scene = texture(texture0, uv);\n    float raw = texture(depthMap, uv).r;\n    if (raw >= 1.0) {\n        finalColor = scene;\n        return;\n    }\n\n    float center = linearDepth(raw);\n    float minimum = center;\n    float maxThickness = thicknessAndDistance.y;\n    for (int i = 0; i < 4; i++) {\n        vec2 stepUv = axes[i] * texel * maxThickness;\n        minimum = min(minimum, min(depthAt(uv - stepUv), depthAt(uv + stepUv)));\n    }\n    float opacity = 1.0 - clamp((minimum - thicknessAndDistance.z) /\n        (thicknessAndDistance.w - thicknessAndDistance.z), 0.0, 1.0);\n    if (opacity <= 0.0) {\n        finalColor = scene;\n        return;\n    }\n\n    float thickness = mix(thicknessAndDistance.x, maxThickness, opacity);\n    vec3 normal = normalAt(uv, vec3(0.0, 0.0, 1.0));\n    float curvature = 0.0;\n    float depthJump = 0.0;\n    for (int i = 0; i < 4; i++) {\n        vec2 stepUv = axes[i] * texel * thickness;\n        vec2 a = uv - stepUv;\n        vec2 b = uv + stepUv;\n        depthJump += (depthAt(a) - center) + (depthAt(b) - center);\n        vec3 difference = normalAt(a, normal) - normalAt(b, normal);\n        curvature += dot(difference, difference);\n    }\n\n    vec3 towardCamera = normalize(-viewPosition(uv, 1.0));\n    float grazing = pow(1.0 - clamp(dot(normalize(normal), towardCamera), 0.0, 1.0), 5.0);\n    float threshold = edgeThresholds.x * (1.0 + edgeThresholds.w * grazing);\n    float depthEdge = smoothstep(threshold * 0.75, threshold * 1.25, depthJump);\n    float normalEdge = smoothstep(edgeThresholds.y - edgeThresholds.z,\n        edgeThresholds.y + edgeThresholds.z, 0.5 * sqrt(curvature));\n\n    float ink = max(depthEdge, normalEdge) * outlineColor.a * opacity;\n    finalColor = vec4(mix(scene.rgb, outlineColor.rgb, ink), scene.a);\n}";
}
